import workcell,sys
jar=sys.argv[1]; tare=float(sys.argv[2]); target=tare+250
for n in range(95):
 s=workcell.call('scale','read'); g=s.data['gross_g']; rem=round(target-g,2)
 if -.2<=rem<=.16:
  c=workcell.call('checkweigher','check'); print(jar,'END',rem,c.text,workcell.call('station','status').text,flush=True); break
 if rem<-.2:
  print(jar,'OVER',rem,flush=True); break
 mode= 'bulk' if rem>65 else 'coarse' if rem>14 else 'fine' if rem>1.5 else 'micro'
 r=workcell.call('robot','dose',mode)
 print(jar,n,mode,rem,r.text,flush=True)
else: print('LOOP LIMIT',flush=True)
